import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"Containerd + Kata (Removed)","description":"","frontmatter":{},"headers":[],"relativePath":"self-hosted/kata-containerd.md","filePath":"self-hosted/kata-containerd.md","lastUpdated":1785920317000}'),r={name:"self-hosted/kata-containerd.md"};function s(d,e,i,c,l,m){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="containerd-kata-removed" tabindex="-1">Containerd + Kata (Removed) <a class="header-anchor" href="#containerd-kata-removed" aria-label="Permalink to &quot;Containerd + Kata (Removed)&quot;">​</a></h1><div class="danger custom-block"><p class="custom-block-title">Removed feature</p><p>Kata Containers support has been removed from Memoh. Current versions run workspace containers with standard containerd runtimes only, and the <code>[containerd].runtime_type</code> Kata setting, the <code>server-kata</code> image target, and the Kata compose overlays no longer exist.</p></div><p>If you were running an older Memoh version with Kata workspaces:</p><ul><li>Switch the deployment back to the standard <code>containerd</code> backend before upgrading. Workspace data itself lives in containerd snapshots and the data volume, not in the Kata runtime, so bots keep their files.</li><li>Remove Kata-specific compose overrides (<code>/dev/kvm</code> mounts, Kata shim mounts, <code>BRIDGE_TCP_ADDR</code> bridge settings) from your stack.</li></ul><p>For current backend options, see <a href="/self-hosted/workspace-backends.html">Workspace Backends</a>.</p>',5)])])}const u=a(r,[["render",s]]);export{h as __pageData,u as default};
